"""Image gallery for profile banners and page backgrounds (files generated by scripts/make_profile_gallery.py).

Members can only pick from these keys: no upload, so nothing to moderate or store.
"""

from flask import url_for

# key: (label fr, label en)
BANNERS = {
    "aurora": ("Aurore boréale", "Northern lights"),
    "nebula": ("Nébuleuse", "Nebula"),
    "synthwave": ("Synthwave", "Synthwave"),
    "mountains": ("Crépuscule", "Dusk mountains"),
    "ocean": ("Océan de nuit", "Night ocean"),
    "lowpoly": ("Low poly", "Low poly"),
    "topo": ("Topographie", "Topography"),
    "pixel": ("Ville pixel", "Pixel city"),
    "sakura": ("Sakura", "Sakura"),
    "ember": ("Braises", "Embers"),
    "circuit": ("Circuit", "Circuit"),
    "dunes": ("Dunes", "Dunes"),
}

BACKGROUNDS = {
    "nebula": ("Nébuleuse", "Nebula"),
    "aurora": ("Aurore boréale", "Northern lights"),
    "topo": ("Topographie", "Topography"),
    "circuit": ("Circuit", "Circuit"),
    "pixel": ("Ville pixel", "Pixel city"),
    "dunes": ("Dunes", "Dunes"),
    "ocean": ("Océan de nuit", "Night ocean"),
    "lowpoly": ("Low poly", "Low poly"),
    "starfield": ("Voie lactée", "Milky Way"),
    "hexgrid": ("Hexagones", "Hexagons"),
    "forest": ("Forêt de nuit", "Night forest"),
    "bokeh": ("Bokeh", "Bokeh"),
    "flow": ("Vagues de lignes", "Line waves"),
    "dotgrid": ("Grille de points", "Dot grid"),
    "synthwave": ("Synthwave", "Synthwave"),
    "mountains": ("Crépuscule", "Dusk mountains"),
    "sakura": ("Sakura", "Sakura"),
    "ember": ("Braises", "Embers"),
}


def banner_url(key: str | None, thumb: bool = False) -> str | None:
    if key not in BANNERS:
        return None
    return url_for("static", filename=f"images/profile/banners/{key}{'_thumb' if thumb else ''}.webp")


def background_url(key: str | None, thumb: bool = False) -> str | None:
    if key not in BACKGROUNDS:
        return None
    return url_for("static", filename=f"images/profile/backgrounds/{key}{'_thumb' if thumb else ''}.webp")


def gallery(items: dict, url_fn, lang: str) -> list[dict]:
    """Picker entries: key, label, thumbnail and full image URL."""
    return [
        {"key": key, "label": fr if lang == "fr" else en, "thumb": url_fn(key, thumb=True), "url": url_fn(key)}
        for key, (fr, en) in items.items()
    ]
